const input = $input.first().json;

const execution = input.execution || {};
const workflow = input.workflow || {};
const error = execution.error || {};

function clean(value, max = 3500) {
  if (value === undefined || value === null) return "";
  return String(value).slice(0, max);
}

function inferSeverity(workflowName, nodeName, message) {
  const text = `${workflowName} ${nodeName} ${message}`.toLowerCase();

  if (text.includes("json.parse") || text.includes("invalid json")) return "critical";
  if (text.includes("insert") || text.includes("update") || text.includes("postgres")) return "critical";
  if (text.includes("notion task")) return "critical";

  // In global Error Trigger, I recommend notifying even for upload errors,
  // because the workflow has already failed.
  if (text.includes("supabase") || text.includes("upload")) return "critical";

  return "critical";
}

const workflowName = workflow.name || "Unknown workflow";
const nodeName = execution.lastNodeExecuted || "Unknown node";
const message = clean(error.message || "Unknown error");
const severity = inferSeverity(workflowName, nodeName, message);

const notify = true;

const telegramMessage = [
  severity === "critical" ? "🚨 n8n workflow failed" : "⚠️ n8n workflow warning",
  "",
  `Workflow: ${workflowName}`,
  `Node: ${nodeName}`,
  `Execution: ${execution.id || "unknown"}`,
  execution.url ? `URL: ${execution.url}` : "",
  execution.retryOf ? `Retry of: ${execution.retryOf}` : "",
  execution.mode ? `Mode: ${execution.mode}` : "",
  "",
  `Error: ${message}`
].filter(Boolean).join("\n");

return [
  {
    json: {
      workflow_id: workflow.id || null,
      workflow_name: workflowName,
      execution_id: execution.id || null,
      execution_url: execution.url || null,
      retry_of: execution.retryOf || null,
      execution_mode: execution.mode || null,

      node_name: nodeName,
      severity,
      event_type: severity === "critical" ? "ERROR" : "WARNING",
      error_message: message,
      error_stack: clean(error.stack, 7000),

      notify,
      telegram_message: telegramMessage,

      run_id: null,
      project_page_id: null,
      intake_page_id: null,

      raw_payload: input
    }
  }
];

const error = $('Normalize Error Payload').first().json;
const run = $input.first().json || {};

const runId = run.run_id || null;
const intakePageId = run.intake_page_id || null;
const projectPageId = run.project_page_id || null;

const telegramMessage = [
  error.telegram_message,
  "",
  runId ? `Run ID: ${runId}` : "Run ID: not found",
  projectPageId ? `Project ID: ${projectPageId}` : "Project ID: not found",
  intakePageId ? `Intake ID: ${intakePageId}` : "Intake ID: not found"
].join("\n");

return [
  {
    json: {
      ...error,

      run_id: runId,
      intake_page_id: intakePageId,
      project_page_id: projectPageId,
      run_status: run.status || null,

      telegram_message: telegramMessage
    }
  }
];
